// Index of entities giving the state of Alexa devices (first entity of each active device)
// flow map: { entity uid: [device id, ...] }

const devices = global.get('devices', 'default') || {};

let map = {};
let count = 0;

for (const id in devices) {
    const d = devices[id];
    if (d.active === true && Array.isArray(d.entities) && d.entities.length > 0) {
        const uid = d.entities[0];
        if (!Array.isArray(map[uid])) {
            map[uid] = [];
        }
        map[uid].push(id);
        count++;
    }
}

flow.set('map', map, 'memoryOnly');

// forget states sent for removed devices
let sent = flow.get('sent', 'memoryOnly') || {};
for (const id in sent) {
    if (typeof devices[id] !== 'object') {
        delete sent[id];
    }
}
flow.set('sent', sent, 'memoryOnly');

node.status({ 'fill': 'green', 'shape': 'dot', 'text': count + ' devices' });

// answer only to a link call (startup inject has no caller)
if (!Array.isArray(msg._linkSource)) {

    return;
}

return msg;

// DKNR MQTT messages: entities catalog (discovery) and values (get)
// output: value of an entity giving the state of an Alexa device (topic = entity uid)

const topic = global.get('mqtt.topic', 'default') || '';
const t = typeof msg.topic === 'string' ? msg.topic : '';

if (topic === '' || !t.startsWith(topic + '/')) {

    return;
}

const path = t.slice(topic.length + 1).split('/');
const action = path.shift();

let catalog = global.get('catalog', 'memoryOnly');
if (typeof catalog !== 'object' || catalog === null) {
    catalog = { 'sources': {}, 'parents': {}, 'entities': {}, 'values': {} };
    global.set('catalog', catalog, 'memoryOnly');
}

// empty retained message: removed
const empty = msg.payload === '' || msg.payload === null || (Buffer.isBuffer(msg.payload) && msg.payload.length === 0);
const object = typeof msg.payload === 'object' && msg.payload !== null && !Buffer.isBuffer(msg.payload);

if (action === 'discovery') {
    // source: topic / discovery / source
    if (path.length === 1) {
        if (empty) {
            delete catalog.sources[path[0]];
        } else {
            catalog.sources[path[0]] = object && msg.payload.title ? String(msg.payload.title) : path[0];
        }
    }
    // parent: topic / discovery / source / parent
    else if (path.length === 2) {
        const key = path.join('/');
        if (empty) {
            delete catalog.parents[key];
        } else {
            catalog.parents[key] = object && msg.payload.name ? String(msg.payload.name).replace(/_/g, ' ') : path[1];
        }
    }
    // entity: topic / discovery / source / parent / entity
    else if (path.length === 3) {
        const uid = path.join('/');
        if (empty) {
            delete catalog.entities[uid];
        } else if (object) {
            catalog.entities[uid] = {
                'name': String(msg.payload.name || path[2]),
                'group': String(msg.payload.group || ''),
                'type': String(msg.payload.type || ''),
                'unit': String(msg.payload.unit || ''),
                'options': typeof msg.payload.options === 'object' && msg.payload.options !== null ? msg.payload.options : {}
            };
            if (typeof catalog.sources[path[0]] !== 'string') {
                catalog.sources[path[0]] = path[0];
            }
        }
    }

    return;
}

// value: topic / get / source / parent / entity
if (action !== 'get' || path.length !== 3) {

    return;
}

const uid = path.join('/');
const value = Buffer.isBuffer(msg.payload) ? msg.payload.toString() : msg.payload;
catalog.values[uid] = value;

// entities giving the state of an Alexa device (see custom - map)
const map = flow.get('map', 'memoryOnly') || {};
if (!Array.isArray(map[uid]) || map[uid].length === 0) {

    return;
}

return {
    'topic': uid,
    'payload': value
};

// DKNR value to Alexa device state
// input: topic = entity uid, payload = value
//     or resend = true: send again states of all devices (id = only this device)
// output: topic = device id, payload = VSH state (to the generated tab)

// DKNR value to Alexa (VSH) state, null if the value is not usable
// binary values are 1 / 0, unit rb is an inverted binary (ex: opening 1 = closed)
function vshState(type, def, value) {
    def = def || {};
    const rb = def.unit === 'rb';
    const on = [true, 1, '1', 'true', 'ON', 'on', 'On'].includes(value);
    const num = Number.parseFloat(value);

    switch (type) {
        case 'switch':
            if (def.type === 'number') {

                return isNaN(num) ? null : { 'powerState': num > 0 ? 'ON' : 'OFF' };
            }

            return { 'powerState': on !== rb ? 'ON' : 'OFF' };
        case 'contact':
        case 'motion': {
            const detected = def.type === 'number' ? num > 0 : on;

            return { 'detectionState': detected !== rb ? 'DETECTED' : 'NOT_DETECTED' };
        }
        case 'temperature':

            return isNaN(num) ? null : { 'temperature': Math.round(num * 10) / 10, 'scale': 'CELSIUS' };
        case 'blinds': {
            if (def.type === 'binary') {

                return { 'percentage': on !== rb ? 100 : 0 };
            }
            if (isNaN(num)) {

                return null;
            }
            // Z-Wave multilevel: 99 is fully open
            let p = Math.round(num);
            p = p >= 99 ? 100 : Math.max(0, p);

            return { 'percentage': p };
        }
    }

    return null;
}

// Alexa (VSH) state to readable text
function vshText(type, state) {
    if (state === null || typeof state !== 'object') {

        return '';
    }
    switch (type) {
        case 'switch':

            return state.powerState === 'ON' ? 'Allumé' : 'Eteint';
        case 'contact':

            return state.detectionState === 'DETECTED' ? 'Ouvert' : 'Fermé';
        case 'motion':

            return state.detectionState === 'DETECTED' ? 'Mouvement' : 'Aucun mouvement';
        case 'temperature':

            return String(state.temperature).replace('.', ',') + ' °C';
        case 'blinds':

            return state.percentage + ' %';
    }

    return '';
}

const devices = global.get('devices', 'default') || {};
const catalog = global.get('catalog', 'memoryOnly') || { 'entities': {}, 'values': {} };
const alexa = global.get('describe.alexa', 'memoryOnly') || {};
const map = flow.get('map', 'memoryOnly') || {};

let sent = flow.get('sent', 'memoryOnly');
if (typeof sent !== 'object' || sent === null) {
    sent = {};
    flow.set('sent', sent, 'memoryOnly');
}

let count = 0;

function update(id, force) {
    const dev = devices[id];
    if (typeof dev !== 'object' || dev.active !== true || !Array.isArray(dev.entities) || dev.entities.length === 0) {

        return;
    }

    // state comes from the first entity of the device
    const uid = dev.entities[0];
    const value = catalog.values[uid];
    if (value === undefined) {

        return;
    }

    const state = vshState(dev.type, catalog.entities[uid], value);
    if (state === null) {

        return;
    }

    const key = JSON.stringify(state);
    const now = Date.now();
    const last = sent[id];

    if (!force && typeof last === 'object') {
        if (dev.type === 'temperature' && typeof last.value === 'number') {
            // VSH terms of use: limit sensors traffic
            const delta = Math.abs(state.temperature - last.value);
            if (delta < 0.05) {

                return;
            }
            if (delta < (alexa.temperature_delta || 0.5) && now - last.time < (alexa.temperature_period || 900) * 1000) {

                return;
            }
        } else if (last.key === key) {

            return;
        }
    }

    sent[id] = {
        'key': key,
        'value': dev.type === 'temperature' ? state.temperature : null,
        'time': now
    };

    count++;
    node.send({
        'topic': id,
        'payload': state
    });
}

if (msg.resend === true) {
    if (typeof msg.id === 'string' && msg.id !== '') {
        update(msg.id, true);
    } else {
        for (const id in devices) {
            update(id, true);
        }
    }
    node.status({ 'fill': 'blue', 'shape': 'dot', 'text': 'resend: ' + count });

    return;
}

for (const id of map[msg.topic] || []) {
    update(id, false);
}

if (count > 0) {
    node.status({ 'fill': 'green', 'shape': 'dot', 'text': msg.topic + ': ' + msg.payload });
}

return;

// Alexa order to DKNR commands
// input: output of a VSH device (topic = device id, payload = state asked by Alexa)
// output: one MQTT message per entity of the device (topic / set / source / parent / entity)

const devices = global.get('devices', 'default') || {};
const catalog = global.get('catalog', 'memoryOnly') || { 'entities': {}, 'values': {} };
const alexa = global.get('describe.alexa', 'memoryOnly') || {};
const topic = global.get('mqtt.topic', 'default') || '';

const dev = devices[msg.topic];
const asked = msg.payload;

if (typeof dev !== 'object' || typeof asked !== 'object' || asked === null || topic === '') {

    return;
}

let out = [];
let state = null;

for (const uid of dev.entities || []) {
    const def = catalog.entities[uid] || {};
    const rb = def.unit === 'rb';
    let value;

    if (dev.type === 'switch' && typeof asked.powerState === 'string') {
        const on = asked.powerState === 'ON';
        state = { 'powerState': on ? 'ON' : 'OFF' };
        if (def.type === 'number') {
            // dimmer: keep its level if already on, the scenes of dknr-domotic correct the level
            if (on && Number.parseFloat(catalog.values[uid]) > 0) {

                continue;
            }
            value = on ? (alexa.dimmer_on || 99) : 0;
        } else {
            value = on !== rb ? 1 : 0;
        }
    } else if (dev.type === 'blinds' && Number.isInteger(asked.percentage)) {
        state = { 'percentage': asked.percentage };
        if (def.type === 'binary') {
            value = (asked.percentage >= 50) !== rb ? 1 : 0;
        } else {
            // Z-Wave multilevel: 99 is fully open
            value = Math.max(0, Math.min(99, asked.percentage));
        }
    } else {

        continue;
    }

    out.push({
        'topic': [topic, 'set', uid].join('/'),
        'payload': String(value),
        'qos': 0,
        'retain': false
    });
}

// Alexa already knows the asked state: send it back only if the DKNR value differs (see custom - state)
if (state !== null) {
    let sent = flow.get('sent', 'memoryOnly') || {};
    sent[dev.id] = { 'key': JSON.stringify(state), 'value': null, 'time': Date.now() };
    flow.set('sent', sent, 'memoryOnly');
}

node.status({
    'fill': out.length > 0 ? 'green' : 'yellow',
    'shape': 'dot',
    'text': dev.name + ': ' + (asked.directive || '') + ' (' + out.length + ')'
});

if (out.length === 0) {

    return;
}

return [out];

// Node-RED admin API request, with a token of the editor user (DKNR_USERNAME / DKNR_PASSWORD)
// input: method, path (ex: /flows), payload
// output: statusCode, payload

const alexa = global.get('describe.alexa', 'memoryOnly') || {};
const base = alexa.admin || 'http://127.0.0.1:1880/admin';

async function login() {
    const r = await node.linkcall('custom - http', {
        'method': 'POST',
        'url': base + '/auth/token',
        'headers': { 'Content-Type': 'application/json' },
        'payload': {
            'client_id': 'node-red-admin',
            'grant_type': 'password',
            'scope': '*',
            'username': env.get('DKNR_USERNAME') || 'admin',
            'password': env.get('DKNR_PASSWORD') || 'admin'
        }
    }, { 'timeout': 30000 });

    const token = r.statusCode === 200 && typeof r.payload === 'object' && r.payload !== null ? r.payload.access_token || '' : '';
    flow.set('admin_token', token, 'memoryOnly');

    return token;
}

async function request(token) {
    let headers = {
        'Accept': 'application/json',
        'Authorization': 'Bearer ' + token
    };
    if (msg.payload !== undefined && msg.payload !== '') {
        headers['Content-Type'] = 'application/json';
    }

    return node.linkcall('custom - http', {
        'method': msg.method || 'GET',
        'url': base + msg.path,
        'headers': headers,
        'payload': msg.payload === undefined ? '' : msg.payload
    }, { 'timeout': 90000 });
}

let r = { 'statusCode': 401, 'payload': {} };

try {
    let token = flow.get('admin_token', 'memoryOnly') || await login();
    if (token) {
        r = await request(token);
        // token expired or revoked
        if (r.statusCode === 401) {
            token = await login();
            if (token) {
                r = await request(token);
            }
        }
    }
} catch (e) {
    r = { 'statusCode': 500, 'payload': { 'error': e.message } };
}

node.status({
    'fill': r.statusCode >= 200 && r.statusCode < 300 ? 'green' : 'red',
    'shape': 'dot',
    'text': (msg.method || 'GET') + ' ' + msg.path + ': ' + r.statusCode
});

msg.statusCode = r.statusCode;
msg.payload = r.payload;

return msg;

// (Re)build the Node-RED tab of the VSH nodes from the Alexa devices (admin API)
// input: credentials and connection (optional): new Amazon connection from custom - pair
// output 1: payload = { ok, changed, count, error } / output 2: send again devices states

const alexa = global.get('describe.alexa', 'memoryOnly') || {};
const devices = global.get('devices', 'default') || {};
const ids = alexa.tab;
const types = alexa.types;

function done(payload) {
    msg.payload = payload;
    node.status({
        'fill': payload.ok ? 'green' : 'red',
        'shape': 'dot',
        'text': payload.ok ? (payload.changed ? 'applied: ' : 'unchanged: ') + payload.count : payload.error
    });

    return [msg, null];
}

// stable JSON for comparison
function canon(v) {
    if (Array.isArray(v)) {

        return '[' + v.map(canon).join(',') + ']';
    }
    if (typeof v === 'object' && v !== null) {

        return '{' + Object.keys(v).sort().map(k => JSON.stringify(k) + ':' + canon(v[k])).join(',') + '}';
    }

    return JSON.stringify(v === undefined ? null : v);
}

// active devices, sorted by room and name
const list = Object.values(devices)
    .filter(d => d.active === true && Array.isArray(d.entities) && d.entities.length > 0 && typeof types[d.type] === 'object')
    .sort((a, b) => String(a.room || '').localeCompare(String(b.room || '')) || String(a.name).localeCompare(String(b.name)));

// current flows: find the generated tab by its fixed link in node
const flows = await node.linkcall('custom - admin', { 'method': 'GET', 'path': '/flows' }, { 'timeout': 120000 });
if (flows.statusCode !== 200 || !Array.isArray(flows.payload)) {

    return done({ 'ok': false, 'error': 'admin API: ' + flows.statusCode, 'count': list.length });
}

const linkin = flows.payload.find(n => n.id === ids.in);
const tab = linkin && typeof linkin.z === 'string' ? linkin.z : '';
const current = tab !== '' ? flows.payload.filter(n => n.z === tab) : [];
const oldConnection = flows.payload.find(n => n.id === ids.connection) || {};
const connection = msg.connection || {};

// nodes of the tab, only configuration, logic stays in the custom tab
const per = 4;
let nodes = [{
    'id': ids.comment,
    'type': 'comment',
    'name': 'Onglet généré par dknr-alexa, ne pas modifier',
