// DKNR value to Alexa (VSH) state, null if the value is not usable
// binary values are 1 / 0, unit rb is an inverted binary (ex: opening 1 = closed)
function vshState(type, def, value) {
    def = def || {};
    const rb = def.unit === 'rb';
    const on = [true, 1, '1', 'true', 'ON', 'on', 'On'].includes(value);
    const num = Number.parseFloat(value);

    switch (type) {
        case 'switch':
            if (def.type === 'number') {

                return isNaN(num) ? null : { 'powerState': num > 0 ? 'ON' : 'OFF' };
            }

            return { 'powerState': on !== rb ? 'ON' : 'OFF' };
        case 'contact':
        case 'motion': {
            const detected = def.type === 'number' ? num > 0 : on;

            return { 'detectionState': detected !== rb ? 'DETECTED' : 'NOT_DETECTED' };
        }
        case 'temperature':

            return isNaN(num) ? null : { 'temperature': Math.round(num * 10) / 10, 'scale': 'CELSIUS' };
        case 'blinds': {
            if (def.type === 'binary') {

                return { 'percentage': on !== rb ? 100 : 0 };
            }
            if (isNaN(num)) {

                return null;
            }
            // Z-Wave multilevel: 99 is fully open
            let p = Math.round(num);
            p = p >= 99 ? 100 : Math.max(0, p);

            return { 'percentage': p };
        }
    }

    return null;
}

// Alexa (VSH) state to readable text
function vshText(type, state) {
    if (state === null || typeof state !== 'object') {

        return '';
    }
    switch (type) {
        case 'switch':

            return state.powerState === 'ON' ? 'Allumé' : 'Eteint';
        case 'contact':

            return state.detectionState === 'DETECTED' ? 'Ouvert' : 'Fermé';
        case 'motion':

            return state.detectionState === 'DETECTED' ? 'Mouvement' : 'Aucun mouvement';
        case 'temperature':

            return String(state.temperature).replace('.', ',') + ' °C';
        case 'blinds':

            return state.percentage + ' %';
    }

    return '';
}
// DKNR entity usable by an Alexa device type
function compatible(type, def) {
    if (typeof def !== 'object' || def === null) {

        return false;
    }
    switch (type) {
        case 'switch':
        case 'blinds':

            return def.type === 'binary' || def.type === 'number';
        case 'contact':
        case 'motion':

            return def.type === 'binary';
        case 'temperature':

            return def.type === 'number';
    }

    return false;
}

// DKNR entity names: source / parent / entity
function entityNames(catalog, uid) {
    const path = String(uid).split('/');
    const def = (catalog.entities || {})[uid];

    return {
        'source': (catalog.sources || {})[path[0]] || path[0] || '',
        'parent': (catalog.parents || {})[path[0] + '/' + path[1]] || path[1] || '',
        'entity': def ? def.name : (path[2] || ''),
        'unit': def ? def.unit : '',
        'known': def !== undefined
    };
}

// DKNR entity readable name: parent / entity
function entityLabel(catalog, uid) {
    const n = entityNames(catalog, uid);

    return n.parent + ' / ' + n.entity + (n.known ? '' : ' (introuvable)');
}

// DKNR value with its unit
function entityValue(catalog, uid) {
    const def = (catalog.entities || {})[uid] || {};
    const value = (catalog.values || {})[uid];
    if (value === undefined || value === null || value === '') {

        return '';
    }
    if (typeof def.options === 'object' && def.options !== null && def.options[value] !== undefined) {

        return String(def.options[value]);
    }
    if (def.type === 'binary') {
        const on = [true, 1, '1', 'true', 'ON', 'on'].includes(value);

        return on ? '1' : '0';
    }
    const unit = ['', 'rb', 'chex'].includes(def.unit || '') ? '' : ' ' + def.unit;

    return (typeof value === 'object' ? JSON.stringify(value) : String(value)) + unit;
}

