        rows.push({ 'lbl': lbl, 'val': String(val) });
    }
};
add('Etat', state);
add('Compte Amazon', vsh.email || 'aucun');
add('Connecté le', date(vsh.paired));
add('Abonnement VSH', plan && plan !== 'unknown' ? plan.toUpperCase() : '');
add('Appareils actifs', list.length + ' / ' + Object.keys(devices).length);
add('Modifications', pending ? 'à appliquer' : 'appliquées');
add('Dernière application', date(vsh.time));

// DKNR sources
let used = {};
for (const d of Object.values(devices)) {
    for (const uid of d.entities || []) {
        used[uid] = true;
    }
}
let sources = {};
for (const s in catalog.sources) {
    sources[s] = { 'source': catalog.sources[s] + (catalog.sources[s] !== s ? ' (' + s + ')' : ''), 'parents': 0, 'entities': 0, 'used': 0 };
}
for (const p in catalog.parents) {
    const s = p.split('/')[0];
    if (sources[s]) {
        sources[s].parents++;
    }
}
for (const uid in catalog.entities) {
    const s = uid.split('/')[0];
    if (sources[s]) {
        sources[s].entities++;
        if (used[uid]) {
            sources[s].used++;
        }
    }
}
const srows = Object.keys(sources).sort().map(s => sources[s]);

const active = pairing.active === true;

return [
    { 'payload': rows },
    { 'payload': '', 'enabled': pending && !active, 'class': '' },
    { 'payload': '', 'enabled': !active, 'class': active ? 'remove' : '', 'ui_update': { 'label': vsh.email ? 'Reconnecter à Amazon' : 'Connecter à Amazon' } },
    { 'payload': active ? { 'code': pairing.code || '', 'uri': pairing.uri || '', 'expires': pairing.expires || 0 } : null },
    { 'payload': srows, 'class': srows.length > 0 ? '' : 'remove' }
];

// Connection to Amazon without the Node-RED editor (as the VSH connection node does in the editor)
// 1. VSH version check, 2. Amazon pairing code shown on the page, 3. waiting for the user validation,
// 4. VSH provisioning, 5. connection node created with its credentials (custom - generate)
// input topic: pair (start) or cancel
// output 1: notification / output 2: refresh of the Connexion page

const alexa = global.get('describe.alexa', 'memoryOnly') || {};
const json = { 'Content-Type': 'application/json' };

const notify = text => node.send([{ 'payload': text }, null]);
const render = () => node.send([null, { 'topic': 'pairing' }]);
const http = m => node.linkcall('custom - http', m, { 'timeout': 60000 });
const sleep = ms => new Promise(resolve => setTimeout(resolve, ms));

let pairing = flow.get('pairing', 'memoryOnly') || {};

if (msg.topic === 'cancel' || msg.payload === 'cancel') {
    if (pairing.active === true) {
        pairing.cancel = true;
        flow.set('pairing', pairing, 'memoryOnly');
    }

    return;
}

if (pairing.active === true) {
    notify('Connexion à Amazon déjà en cours');

    return;
}

pairing = { 'active': true, 'cancel': false, 'code': '', 'uri': '', 'expires': 0 };
flow.set('pairing', pairing, 'memoryOnly');
render();

try {
    // 1. installed VSH version, refused by the VSH server if too old
    const mod = await node.linkcall('custom - admin', { 'method': 'GET', 'path': '/nodes/' + alexa.vsh.module }, { 'timeout': 120000 });
    const version = mod.statusCode === 200 && typeof mod.payload === 'object' ? mod.payload.version : '';
    if (!version) {
        throw new Error('module VSH introuvable');
    }

    const check = await http({ 'method': 'GET', 'url': alexa.vsh.backendUrl + '/check_version?version=' + encodeURIComponent(version), 'headers': {} });
    if (check.statusCode !== 200 || typeof check.payload !== 'object' || check.payload === null) {
        throw new Error('serveur VSH injoignable (' + check.statusCode + ')');
    }
    if (check.payload.isAllowedVersion === false) {
        throw new Error(check.payload.updateHint || 'version de VSH refusée, mettre à jour le projet');
    }

    // 2. Amazon pairing code
    const cp = await http({
        'method': 'POST',
        'url': alexa.amazon.codepair,
        'headers': json,
        'payload': { 'response_type': 'device_code', 'client_id': alexa.vsh.lwaClientId, 'scope': 'profile' }
    });
    if (typeof cp.payload !== 'object' || cp.payload === null || !cp.payload.device_code) {
        throw new Error('code Amazon non obtenu (' + cp.statusCode + ')');
    }

    pairing.code = cp.payload.user_code;
    pairing.uri = cp.payload.verification_uri;
    pairing.expires = Date.now() + (Number(cp.payload.expires_in) || 600) * 1000;
    flow.set('pairing', pairing, 'memoryOnly');
    render();

    // 3. waiting for the user validation on amazon.com/code
    let interval = Math.max(5, Number(cp.payload.interval) || 5) * 1000;
    let token = null;
    while (Date.now() < pairing.expires) {
        await sleep(interval);
        if ((flow.get('pairing', 'memoryOnly') || {}).cancel === true) {
            throw new Error('annulée');
        }
        const t = await http({
            'method': 'POST',
            'url': alexa.amazon.token,
            'headers': json,
            'payload': { 'grant_type': 'device_code', 'device_code': cp.payload.device_code, 'user_code': cp.payload.user_code }
        });
        if (typeof t.payload === 'object' && t.payload !== null) {
            if (t.payload.access_token) {
                token = t.payload;
                break;
            }
            if (t.payload.error === 'slow_down') {
                interval += 5000;
            } else if (t.payload.error && t.payload.error !== 'authorization_pending') {
                throw new Error('Amazon : ' + (t.payload.error_description || t.payload.error));
            }
        }
    }
    if (token === null) {
        throw new Error('code expiré');
    }

    // 4. VSH provisioning: certificates of the connection
    const p = await http({
        'method': 'POST',
        'url': alexa.vsh.backendUrl + '/provision',
        'headers': json,
        'payload': { 'accessToken': token.access_token, 'vshVersion': version }
    });
    const c = typeof p.payload === 'object' && p.payload !== null ? p.payload : {};
    if (!c.vshJwt || !c.thingId) {
        throw new Error('provisionnement VSH refusé (' + p.statusCode + ')');
    }

    // 5. connection node with its credentials, encrypted by Node-RED
    const g = await node.linkcall('custom - generate', {
        'credentials': {
            'vshJwt': c.vshJwt || '',
            'refreshToken': token.refresh_token || '',
            'accessToken': token.access_token || '',
            'email': c.email || '',
            'cert': c.cert || '',
            'thingId': c.thingId || '',
            'caCert': c.caCert || '',
            'server': c.server || '',
            'privateKey': c.privateKey || ''
        },
        'connection': {
            'name': c.email || 'dknr-alexa',
            'port': String(c.port || alexa.vsh.port),
            'accessTokenExpiry': String(Date.now() + ((Number(token.expires_in) || 3600) - 15) * 1000)
        }
    }, { 'timeout': 240000 });
    if (typeof g.payload !== 'object' || g.payload.ok !== true) {
        throw new Error('création de la connexion impossible : ' + (g.payload ? g.payload.error : ''));
    }

    let vsh = global.get('vsh', 'default') || {};
    vsh.email = c.email || '';
    vsh.thingId = c.thingId;
    vsh.paired = Date.now();
    global.set('vsh', vsh, 'default');

    notify('Connecté à Amazon : ' + (c.email || c.thingId));
} catch (e) {
    notify('Connexion à Amazon : ' + e.message);
}

flow.set('pairing', {}, 'memoryOnly');
render();

return;

// Apply the Alexa devices changes: rebuild the generated tab (restarts the Amazon connection)
// output 1: notification / output 2: refresh of the Connexion page

const pairing = flow.get('pairing', 'memoryOnly') || {};
if (pairing.active === true) {

    return;
}

let r;
try {
    r = await node.linkcall('custom - generate', {}, { 'timeout': 240000 });
} catch (e) {
    r = { 'payload': { 'ok': false, 'error': e.message } };
}

const p = r.payload || {};

return [
    { 'payload': p.ok ? p.count + ' appareils envoyés vers Alexa' + (p.changed ? '' : ' (aucun changement)') : 'Echec : ' + p.error },
    { 'topic': 'apply' }
];

// Backup download: one-time address of the backup file (see custom - backup - file)
// output: dashboard navigation

const rnd = Array.from({ 'length': 24 }, () => Math.floor(Math.random() * 16).toString(16)).join('');
flow.set('backup', { 'rnd': rnd, 'time': Date.now() }, 'memoryOnly');

return {
    'payload': {
        'url': '/backup/' + rnd + '/dknr-alexa.json'
    }
};

// Backup file: Alexa devices and MQTT configuration
// the Amazon connection is not saved (encrypted Node-RED credentials), connect again after a restore

const backup = flow.get('backup', 'memoryOnly') || {};
flow.set('backup', {}, 'memoryOnly');

if (!backup.rnd || msg.req.params.rnd !== backup.rnd || Date.now() - backup.time > 60000) {
    msg.statusCode = 404;
    msg.payload = 'Not found';

    return msg;
}

const day = new Date().toISOString().slice(0, 10);

msg.statusCode = 200;
msg.headers = {
    'Content-Type': 'application/json; charset=utf-8',
    'Content-Disposition': 'attachment; filename="dknr-alexa-' + day + '.json"'
};
msg.payload = JSON.stringify({
    'project': 'dknr-alexa',
    'version': global.get('describe.app.version', 'memoryOnly') || '',
    'date': new Date().toISOString(),
    'devices': global.get('devices', 'default') || {},
    'mqtt': global.get('mqtt', 'default') || {}
}, null, 4);

return msg;

// Restore a backup file: Alexa devices and MQTT configuration
// output 1: notification / output 2: MQTT settings (reconnection) / output 3: refresh of the devices table

let backup = null;
try {
    backup = JSON.parse(Buffer.isBuffer(msg.payload) ? msg.payload.toString('utf8') : String(msg.payload));
} catch (e) {
    backup = null;
}

if (typeof backup !== 'object' || backup === null || backup.project !== 'dknr-alexa') {

    return [{ 'payload': 'Fichier de sauvegarde dknr-alexa invalide' }, null, null];
}

const types = global.get('describe.alexa.types', 'memoryOnly') || {};

let devices = {};
let count = 0;
if (typeof backup.devices === 'object' && backup.devices !== null) {
    for (const id in backup.devices) {
        const d = backup.devices[id];
        if (typeof d !== 'object' || d === null || !/^[0-9a-f]{16}$/.test(id) || typeof d.name !== 'string' || typeof types[d.type] !== 'object') {
            continue;
        }
        devices[id] = {
            'id': id,
            'name': d.name,
            'room': typeof d.room === 'string' ? d.room : '',
            'type': d.type,
            'entities': Array.isArray(d.entities) ? d.entities.filter(uid => typeof uid === 'string' && uid.split('/').length === 3) : [],
            'active': d.active === true,
            'updated': Number(d.updated) || Date.now()
        };
        count++;
    }
    global.set('devices', devices, 'default');
}

let mqtt = null;
if (typeof backup.mqtt === 'object' && backup.mqtt !== null && typeof backup.mqtt.host === 'string') {
    mqtt = { ...(global.get('describe.mqtt', 'memoryOnly') || {}), ...backup.mqtt };
    global.set('mqtt', mqtt, 'default');
}

flow.set('sent', {}, 'memoryOnly');
flow.set('edit', null, 'memoryOnly');
await node.linkcall('custom - map', {}, { 'timeout': 10000 });

return [
    { 'payload': 'Sauvegarde restaurée : ' + count + ' appareils' + (mqtt ? ' et configuration MQTT' : '') + ', à appliquer dans la page Connexion' },
    mqtt ? { 'payload': mqtt } : null,
    { 'topic': 'restored' }
];

// Import of an old Virtual Smart Home flow export (vsh-virtual-device nodes)
// only names, types and rooms (guessed from names) are kept, devices are new for Alexa
// old topics are translated to DKNR entities with the current catalog:
//   zwave_5_37_0_currentValue -> zwave/5/37_0_currentValue
//   zigbee_Garage_Plug_state -> zigbee/<parent named Garage Plug>/state (same for other sources)
//   rfxcom_0x5C02_temperature -> rfxcom/5C02/temperature
//   topic of a grouped device -> entities found in the function using it
//   scene -> switch on Daikin entities state
// output 1: import report table / output 2: notification / output 3: refresh of the devices table

// DKNR entity usable by an Alexa device type
function compatible(type, def) {
    if (typeof def !== 'object' || def === null) {

        return false;
    }
    switch (type) {
        case 'switch':
        case 'blinds':

            return def.type === 'binary' || def.type === 'number';
        case 'contact':
        case 'motion':

            return def.type === 'binary';
        case 'temperature':

            return def.type === 'number';
    }

    return false;
}

// DKNR entity names: source / parent / entity
function entityNames(catalog, uid) {
    const path = String(uid).split('/');
    const def = (catalog.entities || {})[uid];

    return {
        'source': (catalog.sources || {})[path[0]] || path[0] || '',
        'parent': (catalog.parents || {})[path[0] + '/' + path[1]] || path[1] || '',
        'entity': def ? def.name : (path[2] || ''),
        'unit': def ? def.unit : '',
        'known': def !== undefined
    };
}

// DKNR entity readable name: parent / entity
function entityLabel(catalog, uid) {
    const n = entityNames(catalog, uid);

    return n.parent + ' / ' + n.entity + (n.known ? '' : ' (introuvable)');
}

// DKNR value with its unit
function entityValue(catalog, uid) {
    const def = (catalog.entities || {})[uid] || {};
    const value = (catalog.values || {})[uid];
    if (value === undefined || value === null || value === '') {

        return '';
    }
    if (typeof def.options === 'object' && def.options !== null && def.options[value] !== undefined) {

        return String(def.options[value]);
    }
    if (def.type === 'binary') {
        const on = [true, 1, '1', 'true', 'ON', 'on'].includes(value);

        return on ? '1' : '0';
    }
    const unit = ['', 'rb', 'chex'].includes(def.unit || '') ? '' : ' ' + def.unit;

    return (typeof value === 'object' ? JSON.stringify(value) : String(value)) + unit;
}

let devices = global.get('devices', 'default') || {};
const catalog = global.get('catalog', 'memoryOnly') || { 'sources': {}, 'parents': {}, 'entities': {}, 'values': {} };

const templates = {
    'SWITCH': 'switch',
    'PLUG': 'switch',
    'SCENE': 'switch',
    'DIMMER_SWITCH': 'switch',
    'DIMMABLE_LIGHT_BULB': 'switch',
    'CONTACT_SENSOR': 'contact',
    'MOTION_SENSOR': 'motion',
    'TEMPERATURE_SENSOR': 'temperature',
    'BLINDS': 'blinds'
};

let flows = null;
try {
    flows = JSON.parse(Buffer.isBuffer(msg.payload) ? msg.payload.toString('utf8') : String(msg.payload));
} catch (e) {
    flows = null;
}
if (!Array.isArray(flows)) {

    return [null, { 'payload': 'Fichier invalide : un export de flow Node-RED (JSON) est attendu' }, null];
}

const vsh = flows.filter(n => n && n.type === 'vsh-virtual-device' && typeof n.name === 'string');
const functions = flows.filter(n => n && n.type === 'function' && typeof n.func === 'string');

if (vsh.length === 0) {

    return [null, { 'payload': 'Aucun appareil VSH dans ce fichier' }, null];
}
if (Object.keys(catalog.entities).length === 0) {

    return [null, { 'payload': 'Aucune entité DKNR connue : vérifier la configuration MQTT avant l\'import' }, null];
}

const norm = s => String(s).toLowerCase().replace(/[\s_\-]+/g, '_');

// parents of each source by normalized id and name
let parents = {};
for (const key in catalog.parents) {
    const [s, p] = key.split('/');
    if (!parents[s]) {
        parents[s] = [];
    }
    parents[s].push({ 'id': p, 'key': norm(p) });
    parents[s].push({ 'id': p, 'key': norm(catalog.parents[key]) });
}

// entity of a parent, exact or case insensitive name
function entity(s, p, e) {
    const uid = [s, p, e].join('/');
    if (catalog.entities[uid] !== undefined) {

        return uid;
    }
    const prefix = s + '/' + p + '/';
    const found = Object.keys(catalog.entities).find(u => u.startsWith(prefix) && norm(u.slice(prefix.length)) === norm(e));

    return found || null;
}

// usual entity names by device type, when the old entity name does not exist (ex: zigbee contact)
const usual = {
    'switch': ['state', 'state_l1'],
    'contact': ['contact'],
    'motion': ['occupancy', 'presence', 'motion'],
    'temperature': ['temperature', 'local_temperature', 'temperature1'],
    'blinds': ['position']
};

// entity of a parent from the old name, else the usual or the only entity of the type
function pick(s, p, e, type) {
    const uid = entity(s, p, e);
    if (uid) {

        return uid;
    }
    for (const u of usual[type] || []) {
        const found = entity(s, p, u);
        if (found && compatible(type, catalog.entities[found])) {

            return found;
        }
    }
    const prefix = s + '/' + p + '/';
    const list = Object.keys(catalog.entities).filter(u => u.startsWith(prefix) && compatible(type, catalog.entities[u]));

    return list.length === 1 ? list[0] : null;
}

// old topic to DKNR entity uid
function resolve(topic, type) {
    const m = String(topic).match(/^([a-z0-9]+)_(.+)$/);
    if (!m) {

        return null;
    }
    const s = m[1];
    const rest = m[2];

    // Z-Wave: zwave_<node>_<command class>_<endpoint>_<property>
    const z = rest.match(/^(\d+)_(.+)$/);
    if (s === 'zwave' && z) {
        const uid = entity(s, z[1], z[2]);
        if (uid) {

            return uid;
        }
    }

    // RFXCom: rfxcom_0x<id>_<entity> or rfxcom_0x<id>_<unit>_<entity> (entity<unit>)
    const x = rest.match(/^0x([0-9A-Fa-f]+)_(.+)$/);
    if (s === 'rfxcom' && x) {
        const parent = (parents[s] || []).find(p => p.key === x[1].toLowerCase());
        if (parent) {
            const u = x[2].match(/^(\d+)_(.+)$/);
            const uid = (u ? entity(s, parent.id, u[2] + u[1]) : null) || pick(s, parent.id, x[2], type);
            if (uid) {

                return uid;
            }
        }
    }

    // other sources: <source>_<parent name>_<entity>, longest parent name first
    const r = norm(rest);
    let best = null;
    for (const p of parents[s] || []) {
        if (r.startsWith(p.key + '_') && (best === null || p.key.length > best.key.length)) {
            const uid = pick(s, p.id, r.slice(p.key.length + 1), type);
            if (uid) {
                best = { 'key': p.key, 'uid': uid };
            }
        }
    }

    return best ? best.uid : null;
}

// room from the name: "lumière de la véranda" -> "véranda"
function room(name) {
    const m = String(name).match(/\s(?:de la|du|des|de l')\s?(.+)$/i);

    return m ? m[1].trim() : '';
}

const quoted = code => (code.match(/'([^'\n]+)'|"([^"\n]+)"/g) || []).map(q => q.slice(1, -1));
const known = Object.values(devices).map(d => String(d.name).toLowerCase());

let rows = [];
let created = 0;

for (const n of vsh) {
    const name = n.name.trim();
    const topic = String(n.topic || '');
    const type = templates[n.template];
    let entities = [];
    let missing = [];
    let note = '';

    if (!type) {
        rows.push({ 'name': name, 'topic': topic, 'result': 'ignoré : type ' + n.template + ' non géré' });
        continue;
    }
    if (known.includes(name.toLowerCase())) {
        rows.push({ 'name': name, 'topic': topic, 'result': 'ignoré : déjà présent' });
        continue;
    }

    if (n.template === 'SCENE') {
        // scene replaced by a switch on Daikin entities state
        entities = Object.keys(catalog.entities).filter(uid => /^daikin\/[^\/]+\/state$/.test(uid) && compatible('switch', catalog.entities[uid]));
        note = 'scène remplacée par un interrupteur';
        if (entities.length === 0) {
            missing.push('daikin/*/state');
        }
    } else {
        const uid = resolve(topic, type);
        if (uid) {
            entities.push(uid);
        } else {
            // grouped device: old topics found with this topic in a function
            const fn = functions.find(f => quoted(f.func).includes(topic));
            const olds = fn ? [...new Set(quoted(fn.func).filter(q => q !== topic && /^[a-z0-9]+_.+_.+$/.test(q)))] : [];
            for (const old of olds) {
                const u = resolve(old, type);
                if (u) {
                    entities.push(u);
                } else {
                    missing.push(old);
                }
            }
            if (olds.length === 0) {
                missing.push(topic);
            } else {
                note = 'appareil groupé';
            }
        }
    }

    const id = (() => {
        let i;
        do {
            i = Array.from({ 'length': 16 }, () => Math.floor(Math.random() * 16).toString(16)).join('');
        } while (devices[i] !== undefined || i.startsWith('d0a1e8a0'));

        return i;
    })();

    devices[id] = {
        'id': id,
        'name': name,
        'room': room(name),
        'type': type,
        'entities': entities,
        // device usable only if all its entities are found
        'active': entities.length > 0 && missing.length === 0,
        'updated': Date.now()
    };
    known.push(name.toLowerCase());
    created++;

    let result = entities.length > 0 && missing.length === 0 ? 'importé' : 'importé inactif';
    if (note !== '') {
        result += ', ' + note;
    }
    if (missing.length > 0) {
        result += ', introuvable : ' + missing.join(', ');
    }
    rows.push({ 'name': name, 'topic': topic, 'result': result });
}

global.set('devices', devices, 'default');
await node.linkcall('custom - map', {}, { 'timeout': 10000 });

const inactive = rows.filter(r => r.result.startsWith('importé inactif')).length;

return [
    { 'payload': rows, 'class': '' },
    { 'payload': created + ' appareils importés' + (inactive > 0 ? ' dont ' + inactive + ' inactifs à compléter' : '') + ', à appliquer dans la page Connexion' },
    { 'topic': 'imported' }
];
